INSERT INTO Enclosure (id, name, image, description) VALUES ('454397e2-6461-4a61-9bd8-a1cb167f9593', 'Kronengecko', '', '<p><strong>Summer</strong><strong> </strong><strong> </strong> (April, May, June, July, August, September):</p><p>Day: <strong><span style="color: rgb(217, 150, 148);">24</span>-<span style="color: rgb(192, 80, 77);">28</span></strong><br>Night: <strong><span style="color: rgb(149, 179, 215);">22</span>-<span style="color: rgb(192, 80, 77);">28</span></strong></p><p><strong>Winter</strong> (October, November, December, January, February, March):</p><p>Day: <strong style="color: rgb(217, 150, 148);">22</strong><strong>-<span style="color: rgb(192, 80, 77);">28</span></strong><br>Night: <strong><span style="color: rgb(149, 179, 215);">20</span>-<span style="color: rgb(192, 80, 77);">28</span></strong></p><p><strong>DANGER: Never above <span style="color: rgb(192, 80, 77); text-decoration-line: underline;">29-30</span>!</strong><br></p>');
